head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.vPAGENO = 0;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();

        // 2009.09.01 채권공시 - 채권상장팀인경우, 채권공시제출인만 나오도록 셋팅. 법인사용자구분 화면에서 안보이도록.
        if (js_bond_yn === "Y") {
            // label_3.style.display = "none";

            // cmb_CORP_USR_TP_CD.style.display = "none";

            // setObjectValue(cmb_CORP_USR_TP_CD, "19");    //채권제출인_19

        }
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        await scwin.listNewPassword();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 한달전 날짜 : 20081110: 허기영 요구사항
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_EDATE.setValue($c.ut.cGetToday2());
    rdo_MKT_ID.setValue(js_market);
    if (js_market !== "9") {
        panel_mkt.hide();
    }
    /*
    // 예비심사법인등록버튼 보이기.
    if (js_dep_cd == "3320" || js_dep_cd == "3330" || js_dep_cd == "2520") // 상장심사1팀 상장심사2팀 상장심사1팀
    {
    	showObj(btn_Pre, true);
    } else {
    	showObj(btn_Pre, false);
    }
     */
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listNewPassword();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30700.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30700.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "비밀번호신규 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange = function() {
    try {
        scwin.vCurrPageNo = 1;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.cmb_PerPage_onselchange" });
    }
};

/**
 * @method
 * @name dts_CORP_USR_TP_CD_OnLoadCompleted
 * @description dts_CORP_USR_TP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_CORP_USR_TP_CD_OnLoadCompleted = function(rowcount) {
    try {
        // 채권상장신청자 제거
        dts_CORP_USR_TP_CD.setBroadcast(false);
        for (let i = 1; i <= dts_CORP_USR_TP_CD.getRowCount(); i++) {
            if (dts_CORP_USR_TP_CD.getCellData(i, "VALUE") === "71") {
                dts_CORP_USR_TP_CD.removeRow(i);
                break;
            }
        }
        dts_CORP_USR_TP_CD.setBroadcast(true, true);
        cmb_CORP_USR_TP_CD.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.dts_CORP_USR_TP_CD_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_PassList_OnLoadCompleted
 * @description dts_PassList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_PassList_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vPAGENO === 0) {
            scwin.vCurrPageNo = 1;
        }
        const vTotalCnt = dts_PassList.getCellData(1, "CNT");
        // alert("vTotalCnt=" + vTotalCnt);
        // alert(getObjectValue(cmb_PerPage));
        $c.stf.FillGridHeader2(scwin.pageNoCnt, cmb_PerPage.getValue(), vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.dts_PassList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_PassList_OnLoadError
 * @description dts_PassList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PassList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_PassList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30700.dts_PassList_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.readNewPassword(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30700.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        // 2009.09.01 채권공시관련 - 채권법인검색창
        if (js_bond_yn === "Y") {
            $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30700.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listNewPassword
 * @description list New Password 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listNewPassword = async function() {
    const argv = scwin.listNewPassword.arguments;
    const argc = scwin.listNewPassword.arguments.length;
    scwin.vPAGENO = (argc === 0) ? 0 : scwin.vPAGENO = argv[0];
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
     ******************************************************************/
    if (js_bond_yn === "Y") {
        url += "&MKT_ID=4";
    } else {
        url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    }
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&COM_NM=" + txb_COM_NM.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&APPL_RSLT=" + cmb_APPL_RSLT.getValue();
    url += "&SCREN_ID=" + "ULDSTF30700.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
     ******************************************************************/
    // if(js_bond_yn == "Y"){
    //    url += "&CORP_USR_TP_CD=19";    //채권제출인_19
    // }else{
    url += "&CORP_USR_TP_CD=" + cmb_CORP_USR_TP_CD.getValue();
    // }
    url += "&PAGENO=" + scwin.vPAGENO;
    url += "&PAGESIZE=" + cmb_PerPage.getValue();

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_PassList",
        action : "/ListedCompanyPassword.do",
        ref : "",
        target : "dts_PassList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    $c.stf.comboCbDataSet(cmb_PerPage);
    cmb_APPL_RSLT.setValue("R");
    const sbmOptions = {
        id : "sbm_dts_CORP_USR_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CORP_USR_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 신청구분코드 셋팅
    const sbmOptions2 = {
        id : "sbm_dts_ApplRsltCd",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ApplRsltCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name PageNoCall
 * @description Page No Call 처리
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
    await scwin.listNewPassword(vPageNo);
};

/**
 * @method
 * @name readNewPassword
 * @description read New Password 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readNewPassword = async function(row, colid) {
    if (colid === "INTEG_USR_ID") {
        // var vINTEG_USR_ID = dts_PassList.NameString(row, "INTEG_USR_ID");
        const vINTEG_USR_ID = dts_PassList.getCellData(row, "CORP_USR_REG_APPL_SEQ"); // SEQ
        // alert(vINTEG_USR_ID);
        const options = {
            id: "ULDSTF30701",
            title: "비밀번호 신규조회",
            type: "browserPopup",
            width: "580px",
            height: "800px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/issueinfo/ULDSTF30701.gfm", options);
    } else if (colid === "COM_NM") {
        scwin.gIsurCd = dts_PassList.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name openPre
 * @description 예비심사청구인 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openPre = async function() {
    // 예비심사청구인 등록
    const options = {
        id: "ULDSTF30704",
        title: "예비심사청구인 등록",
        type: "browserPopup",
        width: "370px",
        height: "250px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/issueinfo/ULDSTF30704.gfm", options);
};
